# Try hypothesis: simple full-grid checkerboard using background and special values
# Background = 9, special values present: 5 and 1

def make_checkerboard(h, w, val1, val2):
    result = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if (r + c) % 2 == 0:
                result[r][c] = val1
            else:
                result[r][c] = val2
    return result

